<script lang="ts">
 import {onMount,tick} from 'svelte'
 const uid=$props.id()
 let mounted=$state(false), help=$state(false), dismissed=$state(false), hovered=$state(false), shortcuts=$state(false), count=$state(0), note=$state('Retained detail'), items=$state(['Field notes','Research archive','Regional study']), message=$state('')
 onMount(()=>{mounted=true})
 async function move(item:string,delta:number){const from=items.indexOf(item),to=from+delta;if(to<0||to>=items.length)return;items=[...items];[items[from],items[to]]=[items[to],items[from]];message=`${item} moved to ${to+1} of ${items.length}.`;await tick();document.getElementById(`${uid}-${item}-${delta}`)?.focus()}
 function shortcut(event:KeyboardEvent){const target=event.target as HTMLElement;if(!target.closest('[data-study=interaction]')||!shortcuts||event.isComposing||event.ctrlKey||event.altKey||event.metaKey||target.closest('input,textarea,select,[contenteditable="true"]'))return;if(event.key==='n'){event.preventDefault();count++}}
</script>
<svelte:window onkeydown={shortcut}/>
<section class="task-study" data-study="interaction" aria-label="Help, disclosure and reorder">
 <fieldset disabled={!mounted}><legend class="study-sr">Local interaction tasks</legend>
 <h4>Supplementary help</h4><div class="help-region" role="group" aria-label="Supplementary storage help" onpointerenter={()=>hovered=true} onpointerleave={e=>{hovered=false;if(!e.currentTarget.contains(document.activeElement))help=false}} onfocusout={e=>{if(!hovered&&e.relatedTarget&&!e.currentTarget.contains(e.relatedTarget as Node)){help=false;dismissed=false}}} onkeydown={e=>{if(e.key==='Escape'){help=false;dismissed=true;document.getElementById(`${uid}-trigger`)?.focus();e.stopPropagation()}}}><button id={`${uid}-trigger`} class="btn" aria-expanded={help} aria-controls={`${uid}-help`} onpointerenter={()=>{dismissed=false;help=true}} onfocus={()=>{if(!dismissed)help=true}} onclick={()=>{dismissed=false;help=true}} onkeydown={e=>{if(e.key==='Escape'){help=false;dismissed=true;e.stopPropagation()}}}>About local storage</button>{#if help}<div class="help-popup" id={`${uid}-help`} role="note">Values live only in this page. Reloading resets them.<button class="btn" onclick={()=>{help=false;dismissed=true;document.getElementById(`${uid}-trigger`)?.focus()}}>Dismiss help</button></div>{/if}</div><p>Essential instruction: no information is sent. This supplementary popup is a disclosure, not a tooltip containing controls.</p>
 <h4>Optional details</h4><details><summary>Show editable details</summary><label class="study-field">Detail note<input class="input" bind:value={note}/></label></details>
 <h4>Local shortcut</h4><label class="check"><input class="checkbox" type="checkbox" bind:checked={shortcuts}/> Enable n while focus is in this specimen, outside fields</label><button class="btn" onclick={()=>count++}>Create local note</button><p>Notes created: {count}. Typing in the detail field must not run the command.</p>
 <h4>Manual order</h4><ol class="move-list">{#each items as item,i (item)}<li><span>{item}</span><div class="study-actions"><button id={`${uid}-${item}--1`} class="btn" aria-disabled={i===0} onclick={()=>move(item,-1)}>Move {item} up</button><button id={`${uid}-${item}-1`} class="btn" aria-disabled={i===items.length-1} onclick={()=>move(item,1)}>Move {item} down</button></div></li>{/each}</ol><p role="status">{message}</p>
 <button class="btn" onclick={()=>{items=['Field notes','Research archive','Regional study'];help=shortcuts=false;count=0;note='Retained detail';message='Reset local tasks.'}}>Reset interactions</button></fieldset><noscript>Examples remain readable; operations require JavaScript.</noscript>
</section>
<style>.help-region{position:relative;padding-bottom:8px}.help-popup{padding:12px;border:1px solid var(--color-line-strong);max-width:26rem;background:var(--color-surface-inset)}.help-popup button{display:block;margin-top:8px}.move-list{padding-inline-start:1.5em}.move-list li{padding-block:8px;border-block-end:1px solid var(--color-line-divider)}[aria-disabled=true]{opacity:.6}</style>
